//! The context graph (ADR 0084, ADR 0086): what Rubato knows about the repositories on the map,
//! generated by the server on a timer, copied to each companion and read by agents through
//! read-only MCP tools. The graph is a set of sources, each regenerated and replaced whole.
//!
//! This module is the wire shape only: a node, an edge, a source as the server announces it
//! (`ServerMessage::GraphSources`, seam `companion-server`), the lines of a snapshot, and the
//! status the Overview carries (seam `web-server`). The graph is never an input to progress,
//! pins, plans or approvals.

use chrono::{DateTime, Utc};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

/// The format number in a snapshot's header. A reader refuses any other.
pub const SNAPSHOT_FORMAT: u32 = 1;

/// The kinds of source, node and edge this version writes. They travel as strings, and a reader
/// keeps one it does not know, so a later kind is additive for an older companion.
pub mod kind {
    /// Source kinds, also the first segment of a source key.
    pub mod source {
        /// One repository at its default-branch head: files, symbols, decision documents.
        pub const REPO: &str = "repo";
        /// One workspace: its map and its pins.
        pub const WORKSPACE: &str = "workspace";
        /// The facts the server keeps per repository and shares across workspaces (ADR 0047).
        pub const TEAM: &str = "team";
    }

    pub mod node {
        pub const PART: &str = "part";
        pub const SEAM: &str = "seam";
        pub const REPO: &str = "repo";
        pub const ISSUE: &str = "issue";
        pub const PLAN: &str = "plan";
        pub const PULL: &str = "pull";
        pub const FILE: &str = "file";
        pub const SYMBOL: &str = "symbol";
        pub const PACKAGE: &str = "package";
        pub const ADR: &str = "adr";
        pub const SCENARIO: &str = "scenario";
        pub const SLICE: &str = "slice";
        pub const ALL: &[&str] = &[
            PART, SEAM, REPO, ISSUE, PLAN, PULL, FILE, SYMBOL, PACKAGE, ADR, SCENARIO, SLICE,
        ];
    }

    pub mod edge {
        /// seam → part, with `role` (`from` or `to`) and `owner` in the detail.
        pub const JOINS: &str = "joins";
        /// part → part: one declared flow, with its seam, kind and what it carries.
        pub const FLOW: &str = "flow";
        /// part → repo, with the path inside it.
        pub const BACKED_BY: &str = "backed_by";
        /// issue → part or seam.
        pub const PINNED_TO: &str = "pinned_to";
        /// plan → issue.
        pub const PLANS: &str = "plans";
        /// plan → `map:<id>`: a part the plan lists as affected.
        pub const AFFECTS: &str = "affects";
        /// plan → `map:<id>`: a seam the plan touches.
        pub const TOUCHES: &str = "touches";
        /// plan → adr.
        pub const CITES: &str = "cites";
        /// pull → issue: the branch names the issue.
        pub const FOR: &str = "for";
        /// file → symbol.
        pub const DEFINES: &str = "defines";
        /// file → file, or file → package.
        pub const IMPORTS: &str = "imports";
        /// file → symbol, resolved by name; only when exactly one definition matches.
        pub const REFERENCES: &str = "references";
        /// adr → adr.
        pub const SUPERSEDES: &str = "supersedes";
        /// adr → `map:<id>`, for each id in its `Seam:` field.
        pub const GOVERNS: &str = "governs";
        pub const ALL: &[&str] = &[
            JOINS, FLOW, BACKED_BY, PINNED_TO, PLANS, AFFECTS, TOUCHES, CITES, FOR, DEFINES,
            IMPORTS, REFERENCES, SUPERSEDES, GOVERNS,
        ];
    }
}

/// Source keys: `repo/<owner>/<name>`, `workspace/<tenant>/<id>` and `team/<tenant>` (ADR 0087).
/// A key names what a source was built from; a node id never has this form. A workspace's and a
/// team's key say their tenant; a repository's tenant is the one it is live in.
pub mod source_key {
    use super::kind::source::{REPO, TEAM as TEAM_KIND, WORKSPACE};

    /// The source of one tenant's shared facts.
    pub fn team(tenant: &str) -> String {
        format!("{TEAM_KIND}/{tenant}")
    }

    /// The source of the repository `owner/name`.
    pub fn repo(owner_name: &str) -> String {
        format!("{REPO}/{owner_name}")
    }

    /// The source of the workspace `id` of `tenant`.
    pub fn workspace(tenant: &str, id: &str) -> String {
        format!("{WORKSPACE}/{tenant}/{id}")
    }

    /// The repository a `repo/<owner>/<name>` key names.
    pub fn repo_of(key: &str) -> Option<&str> {
        (kind_of(key) == Some(REPO)).then(|| &key["repo/".len()..])
    }

    /// The tenant a workspace or team key names; `None` for a repository's key, whose tenant
    /// the key does not say, and for anything that is not a key.
    pub fn tenant_of(key: &str) -> Option<&str> {
        match kind_of(key)? {
            k if k == TEAM_KIND => key.strip_prefix("team/"),
            k if k == WORKSPACE => key.strip_prefix("workspace/")?.split_once('/').map(|p| p.0),
            _ => None,
        }
    }

    /// The kind a well-formed key names, or `None` for anything else, the keys of before
    /// tenants (`team`, `workspace/<id>`) among them. A key this version does not know is not
    /// an error on the wire; it is only never built or asked for here.
    pub fn kind_of(key: &str) -> Option<&'static str> {
        if let Some(tenant) = key.strip_prefix("team/") {
            return crate::tenant::is_tenant_id(tenant).then_some(TEAM_KIND);
        }
        if let Some(rest) = key.strip_prefix("workspace/") {
            let (tenant, id) = rest.split_once('/')?;
            return (crate::tenant::is_tenant_id(tenant) && crate::workspace::is_workspace_id(id))
                .then_some(WORKSPACE);
        }
        let rest = key.strip_prefix("repo/")?;
        let (owner, name) = rest.split_once('/')?;
        let part = |s: &str| {
            !s.is_empty()
                && s.len() <= 100
                && s.bytes()
                    .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.'))
        };
        (part(owner) && part(name)).then_some(REPO)
    }
}

/// Node ids. Global, readable, and each produced by exactly one source, so asking for an id has
/// one answer.
pub mod id {
    /// A map part in one workspace.
    pub fn part(workspace: &str, map_id: &str) -> String {
        format!("part:{workspace}/{map_id}")
    }
    /// A seam in one workspace.
    pub fn seam(workspace: &str, map_id: &str) -> String {
        format!("seam:{workspace}/{map_id}")
    }
    /// A map id with no workspace, as a plan or an ADR names it. Never a node: an edge target
    /// that is resolved against the parts and seams of every workspace that names the repo.
    pub fn map_ref(map_id: &str) -> String {
        format!("map:{map_id}")
    }
    pub fn repo(owner_name: &str) -> String {
        format!("repo:{owner_name}")
    }
    pub fn issue(owner_name: &str, number: u64) -> String {
        format!("issue:{owner_name}#{number}")
    }
    pub fn plan(owner_name: &str, number: u64) -> String {
        format!("plan:{owner_name}#{number}")
    }
    pub fn pull(owner_name: &str, number: u64) -> String {
        format!("pull:{owner_name}#{number}")
    }
    pub fn file(owner_name: &str, path: &str) -> String {
        format!("file:{owner_name}:{path}")
    }
    pub fn symbol(owner_name: &str, path: &str, qualified: &str) -> String {
        format!("sym:{owner_name}:{path}#{qualified}")
    }
    /// An import that leaves the repository. Per repository, so one source produces it.
    pub fn package(owner_name: &str, ecosystem: &str, name: &str) -> String {
        format!("pkg:{owner_name}:{ecosystem}/{name}")
    }
    pub fn adr(owner_name: &str, number: &str) -> String {
        format!("adr:{owner_name}:{number}")
    }
    /// `tag` is the scenario's `@<capability>.<slug>` (ADR 0069).
    pub fn scenario(owner_name: &str, tag: &str) -> String {
        format!("scenario:{owner_name}:{tag}")
    }
    pub fn slice(owner_name: &str, deployable: &str, name: &str) -> String {
        format!("slice:{owner_name}:{deployable}/{name}")
    }
}

fn is_false(b: &bool) -> bool {
    !*b
}

/// One thing the graph knows about. No file contents: for code a name, a path, a line range and
/// one signature line; for a decision document its capped Decision section (ADR 0084).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct GraphNode {
    /// See [`id`]. Unique across every source.
    pub id: String,
    /// One of [`kind::node`], or a later kind this reader keeps without knowing it.
    pub kind: String,
    pub name: String,
    /// `owner/name`, where the node belongs to one repository.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub repo: Option<String>,
    /// Path inside that repository.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
    /// First line, 1-based.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub line: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub end_line: Option<u32>,
    /// One line a search may match and show: a signature, a title, a description.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub summary: Option<String>,
    /// What else this kind carries. Never a progress state and never a session.
    #[serde(default, skip_serializing_if = "Map::is_empty")]
    pub detail: Map<String, Value>,
}

/// One relation. `to` may be a node of another source, or a `map:<id>` reference; an edge whose
/// target is not in a copy yet is kept and resolves when it is.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
pub struct GraphEdge {
    pub from: String,
    /// One of [`kind::edge`], or a later kind this reader keeps without knowing it.
    pub kind: String,
    pub to: String,
    #[serde(default, skip_serializing_if = "Map::is_empty")]
    pub detail: Map<String, Value>,
}

/// One source as the server announces it to a companion.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct GraphSourceInfo {
    /// See [`source_key`].
    pub source: String,
    /// One of [`kind::source`].
    pub kind: String,
    /// The default-branch head a repo source was built at.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub head_sha: Option<String>,
    /// The map version a workspace source was built from.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub map_version: Option<String>,
    /// `sha256:<hex>` over the snapshot's lines after the header. The same graph always has the
    /// same hash, so an unchanged source is never fetched twice.
    pub content_hash: String,
    pub generated_at: DateTime<Utc>,
    pub nodes: u64,
    pub edges: u64,
    /// A cap cut this source (`limits::GRAPH_*`). Not a failure; every answer from it says so.
    #[serde(default, skip_serializing_if = "is_false")]
    pub truncated: bool,
}

/// `ServerMessage::GraphSources`: every source the companion may hold, the whole list each time
/// (ADR 0086). The companion fetches what differs from its copy and deletes what the list no
/// longer names. Sent only to a companion that announced `capability::CONTEXT_GRAPH` and whose
/// owner may read the graph.
#[derive(Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize, JsonSchema)]
pub struct GraphSources {
    /// At most `limits::GRAPH_SOURCES_MAX`.
    #[schemars(length(max = 64))]
    pub sources: Vec<GraphSourceInfo>,
}

impl GraphSources {
    /// The count, when it is over the cap. The server never sends such a list; a companion that
    /// receives one applies nothing from it.
    pub fn check(&self) -> Result<(), usize> {
        if self.sources.len() > crate::limits::GRAPH_SOURCES_MAX {
            Err(self.sources.len())
        } else {
            Ok(())
        }
    }
}

/// The first line of a snapshot body (`routes::GRAPH_SNAPSHOT`).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct GraphSnapshotHeader {
    /// [`SNAPSHOT_FORMAT`].
    pub format: u32,
    pub source: String,
    pub kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub head_sha: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub map_version: Option<String>,
    /// The extraction's version; a bump rebuilds every source once.
    pub generator: u32,
    /// Over the lines after this one, as [`GraphSourceInfo::content_hash`].
    pub content_hash: String,
    pub generated_at: DateTime<Utc>,
    pub nodes: u64,
    pub edges: u64,
    #[serde(default, skip_serializing_if = "is_false")]
    pub truncated: bool,
}

/// Every line of a snapshot body after the header: the nodes in id order, then the edges in
/// (`from`, `kind`, `to`, `detail`) order.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum GraphSnapshotLine {
    Node(GraphNode),
    Edge(GraphEdge),
}

/// `?source=` of the snapshot route.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct SnapshotQuery {
    pub source: String,
}

/// One source as the Overview shows it: what [`GraphSourceInfo`] says, with the build's own
/// times, and nothing built yet as a state of its own.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct GraphSourceStatus {
    pub source: String,
    pub kind: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub head_sha: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub map_version: Option<String>,
    /// Absent until the first build.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub generated_at: Option<DateTime<Utc>>,
    /// When a tick last found the stored rows current. Its age is what "stale" is judged from.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub checked_at: Option<DateTime<Utc>>,
    /// The newest build's error, when the newest build failed. The rows are the last good ones.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
    #[serde(default)]
    pub nodes: u64,
    #[serde(default)]
    pub edges: u64,
    #[serde(default, skip_serializing_if = "is_false")]
    pub truncated: bool,
}

/// `Overview.graph`: absent while the server's context graph flag is off.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, JsonSchema)]
pub struct GraphOverview {
    /// The regeneration interval, so the web can say when a source is stale.
    pub regen_secs: u32,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub sources: Vec<GraphSourceStatus>,
}

/// Why the snapshot route refused.
pub mod reason {
    /// The server's context graph flag is off: 404.
    pub const CONTEXT_GRAPH_OFF: &str = "context_graph_off";
    /// The pairing's owner has no team record at most 7 days old (ADR 0022, ADR 0086): 403.
    pub const TEAM_RECORD_STALE: &str = "team_record_stale";
    /// No such source: 404.
    pub const UNKNOWN_SOURCE: &str = "unknown_source";
}

pub mod routes {
    /// `GET …?source=<source key>` with the pairing token as bearer (ADR 0086): one source as
    /// gzipped NDJSON, a [`super::GraphSnapshotHeader`] line and then
    /// [`super::GraphSnapshotLine`]s. Team-scoped, never under `/api/w/{ws}`.
    pub const GRAPH_SNAPSHOT: &str = "/api/graph/snapshot";
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::message::ServerMessage;
    use serde_json::json;

    fn info(source: &str, kind: &str) -> GraphSourceInfo {
        GraphSourceInfo {
            source: source.into(),
            kind: kind.into(),
            head_sha: None,
            map_version: None,
            content_hash: "sha256:00".into(),
            generated_at: "2026-11-26T17:00:04Z".parse().unwrap(),
            nodes: 1,
            edges: 0,
            truncated: false,
        }
    }

    #[test]
    fn graph_sources_round_trips_as_a_server_message() {
        let msg = ServerMessage::GraphSources(GraphSources {
            sources: vec![info("repo/m0x6A/rubato", kind::source::REPO)],
        });
        let v = serde_json::to_value(&msg).unwrap();
        assert_eq!(v["type"], "graph_sources");
        assert_eq!(v["sources"][0]["source"], "repo/m0x6A/rubato");
        // Absent, not false and not null: an unchanged source serialises the same way always.
        assert!(v["sources"][0].get("truncated").is_none());
        assert!(v["sources"][0].get("head_sha").is_none());
        assert_eq!(serde_json::from_value::<ServerMessage>(v).unwrap(), msg);
    }

    #[test]
    fn a_kind_this_reader_does_not_know_is_kept() {
        let node: GraphNode = serde_json::from_value(json!({
            "id": "runbook:m0x6A/rubato:deploy", "kind": "runbook", "name": "Deploy"
        }))
        .unwrap();
        assert_eq!(node.kind, "runbook");
        assert!(!kind::node::ALL.contains(&node.kind.as_str()));
        let edge: GraphEdge = serde_json::from_value(json!({
            "from": "runbook:m0x6A/rubato:deploy", "kind": "documents", "to": "part:default/web"
        }))
        .unwrap();
        assert_eq!(edge.kind, "documents");
        let source: GraphSourceInfo = serde_json::from_value(json!({
            "source": "org/acme", "kind": "org", "content_hash": "sha256:00",
            "generated_at": "2026-11-26T17:00:04Z", "nodes": 0, "edges": 0
        }))
        .unwrap();
        assert_eq!(source.kind, "org");
        assert_eq!(source_key::kind_of(&source.source), None);
    }

    #[test]
    fn a_list_over_the_cap_fails_its_check() {
        let list = |n: usize| GraphSources {
            sources: (0..n)
                .map(|i| info(&format!("repo/o/r{i}"), kind::source::REPO))
                .collect(),
        };
        assert_eq!(list(crate::limits::GRAPH_SOURCES_MAX).check(), Ok(()));
        // The fixture that makes the check fail on purpose.
        assert_eq!(list(crate::limits::GRAPH_SOURCES_MAX + 1).check(), Err(257));
    }

    #[test]
    fn a_snapshot_line_is_a_node_or_an_edge_and_the_header_is_its_own_line() {
        let node = GraphSnapshotLine::Node(GraphNode {
            id: id::file("m0x6A/rubato", "crates/rubato-server/src/lib.rs"),
            kind: kind::node::FILE.into(),
            name: "lib.rs".into(),
            repo: Some("m0x6A/rubato".into()),
            path: Some("crates/rubato-server/src/lib.rs".into()),
            line: None,
            end_line: None,
            summary: None,
            detail: Map::from_iter([("language".to_owned(), json!("rust"))]),
        });
        let text = serde_json::to_string(&node).unwrap();
        assert!(
            text.starts_with(r#"{"node":{"id":"file:m0x6A/rubato:crates/"#),
            "{text}"
        );
        assert_eq!(
            serde_json::from_str::<GraphSnapshotLine>(&text).unwrap(),
            node
        );
        let edge: GraphSnapshotLine = serde_json::from_value(json!({
            "edge": { "from": "a", "kind": "imports", "to": "b" }
        }))
        .unwrap();
        assert!(matches!(edge, GraphSnapshotLine::Edge(e) if e.detail.is_empty()));
        // A header is not a line: a reader that reads past it by mistake fails, not misreads.
        let header = json!({
            "format": SNAPSHOT_FORMAT, "source": "team", "kind": "team", "generator": 1,
            "content_hash": "sha256:00", "generated_at": "2026-11-26T17:00:04Z",
            "nodes": 0, "edges": 0
        });
        assert!(serde_json::from_value::<GraphSnapshotHeader>(header.clone()).is_ok());
        assert!(serde_json::from_value::<GraphSnapshotLine>(header).is_err());
    }

    #[test]
    fn source_keys_name_their_kind_and_ids_never_look_like_keys() {
        let cases = [
            (source_key::repo("m0x6A/rubato"), Some(kind::source::REPO)),
            (
                source_key::workspace("acme", "default"),
                Some(kind::source::WORKSPACE),
            ),
            (source_key::team("acme"), Some(kind::source::TEAM)),
            // The keys of before tenants name nothing now.
            ("team".to_owned(), None),
            ("workspace/default".to_owned(), None),
            ("team/Not A Tenant".to_owned(), None),
            ("workspace/acme/Not An Id".to_owned(), None),
            ("repo/m0x6A".to_owned(), None),
            ("repo/m0x6A/rubato/extra".to_owned(), None),
            ("repo//rubato".to_owned(), None),
            ("workspace/Not An Id".to_owned(), None),
            (id::repo("m0x6A/rubato"), None),
            (id::part("default", "web"), None),
        ];
        for (key, want) in &cases {
            assert_eq!(source_key::kind_of(key), *want, "{key}");
        }
        assert_eq!(
            source_key::tenant_of(&source_key::team("acme")),
            Some("acme")
        );
        assert_eq!(
            source_key::tenant_of(&source_key::workspace("acme", "main")),
            Some("acme")
        );
        assert_eq!(
            source_key::tenant_of(&source_key::repo("m0x6A/rubato")),
            None
        );
        assert_eq!(
            source_key::repo_of(&source_key::repo("m0x6A/rubato")),
            Some("m0x6A/rubato")
        );
        assert_eq!(source_key::repo_of("team/acme"), None);
        println!("checked {} source keys", cases.len());
    }

    #[test]
    fn an_overview_status_before_the_first_build_has_no_times() {
        let s: GraphSourceStatus =
            serde_json::from_value(json!({ "source": "team", "kind": "team" })).unwrap();
        assert!(s.generated_at.is_none() && s.checked_at.is_none() && s.error.is_none());
        assert_eq!(
            serde_json::to_value(&s).unwrap(),
            json!({ "source": "team", "kind": "team", "nodes": 0, "edges": 0 })
        );
    }
}
